import { Component, Input, Output, EventEmitter } from '@angular/core';

// ❌ OLD: Decorator-based API. Inputs are plain fields (not reactive),
// outputs need EventEmitter, and two-way binding requires a manual
// [x] + (xChange) pair with hand-written emit calls.
@Component({
  selector: 'app-counter',
  template: `
    <button (click)="inc()">+1</button>
    <p>Value: {{ count }}</p>
  `,
})
export class CounterComponent {
  @Input() count = 0; // ❌ OLD: plain field, not a signal
  @Output() changed = new EventEmitter<number>();
  // ❌ OLD: manual two-way plumbing requires a matching Change output
  @Output() countChange = new EventEmitter<number>();

  inc() {
    this.count++;
    this.changed.emit(this.count); // ❌ OLD: two emits to keep both in sync
    this.countChange.emit(this.count);
  }
}

