import { Component, input, output, model } from '@angular/core';

// ✅ NEW: Signal-based API. Inputs are reactive signals (bindings that
// read them update granularly), outputs are typed emitter refs, and
// model() gives two-way binding with zero manual plumbing.
@Component({
  selector: 'app-counter',
  template: `
    <button (click)="inc()">+1</button>
    <p>Value: {{ count() }}</p> <!-- ✅ NEW: reactive read -->
  `,
})
export class CounterComponent {
  count = input(0); // ✅ NEW: read-only input signal
  changed = output<number>(); // ✅ NEW: typed output emitter
  countModel = model(0); // ✅ NEW: [(countModel)] two-way binding

  inc() {
    this.changed.emit(this.count() + 1); // ✅ NEW: emit once
    this.countModel.update((v) => v + 1); // ✅ NEW: parent sees the change
  }
}
